package android.text;import java.util.*;public class SpannableString implements CharSequence {private String text;public final List<Object> spans=new ArrayList<Object>();public final List<int[]> ranges=new ArrayList<int[]>();public SpannableString(CharSequence s){text=s.toString();}public void setSpan(Object s,int start,int end,int flags){spans.add(s);ranges.add(new int[]{start,end,flags});}public int length(){return text.length();}public char charAt(int i){return text.charAt(i);}public CharSequence subSequence(int s,int e){return text.subSequence(s,e);}public String toString(){return text;}}
